              "quote": "[…] son lever, son déjeuner, son repos, prendre par leur singularité despotique un peu de l’intérêt de ce que Saint-Simon appelait la « mécanique » de la vie à Versailles, et pouvait croire aussi que ses silences, une nuance de bonne humeur ou de hauteur dans sa physionomie, étaient de la part de Françoise l’objet d’un commentaire aussi passionné, aussi craintif que l’étaient le silence, la bonne humeur, la hauteur du Roi quand un courtisan, ou même les plus grands seigneurs, lui avaient remis une supplique, au détour d’une allée, à Versailles.",
