              "quote": "Il en avait eu souvent la pensée. Maintenant qu’il s’était remis à son étude sur Ver Meer il aurait eu besoin de retourner au moins quelques jours à la Haye, à Dresde, à Brunswick. Il était persuadé qu’une « Toilette de Diane » qui avait été achetée par le Mauritshuis à la vente Goldschmidt comme un Nicolas Maes était en réalité de Ver Meer. Et il aurait voulu pouvoir étudier le tableau sur place pour étayer sa conviction. Mais quitter Paris pendant qu’Odette y était et même quand elle était absente — car dans des lieux nouveaux où les sensations ne sont pas amorties par l’habitude, on retrempe, on ranime une […]",
