              "quote": "[…] remet en nos mains la possibilité de leur apparition, soustraite à la tutelle et dispensée de l’agrément du hasard, de même la production de ces rêves d’Atlantique et d’Italie cessa d’être soumise uniquement aux changements des saisons et du temps. Je n’eus besoin pour les faire renaître que de prononcer ces noms : Balbec, Venise, Florence, dans l’intérieur desquels avait fini par s’accumuler le désir que m’avaient inspiré les lieux qu’ils désignaient. Même au printemps, trouver dans un livre le nom de Balbec suffisait à réveiller en moi le désir des tempêtes et du gothique normand ; même par un jour de […]",
