              "quote": "[…] au nez de Mascarille plutôt qu’à celui de Salomon. Mais Bloch n’ayant pas été assoupli par la gymnastique du « Faubourg », ni ennobli par un croisement avec l’Angleterre ou l’Espagne, restait, pour un amateur d’exotisme, aussi étrange et savoureux à regarder, malgré son costume européen, qu’un Juif de Decamps. Admirable puissance de la race qui du fond des siècles pousse en avant jusque dans le Paris moderne, dans les couloirs de nos théâtres, derrière les guichets de nos bureaux, à un enterrement, dans la rue, une phalange intacte stylisant la coiffure moderne, absorbant, faisant oublier, disciplinant la […]",
              "language": "fr",
              "url": "https://fr.wikisource.org/wiki/Le_C%C3%B4t%C3%A9_de_Guermantes%2FDeuxi%C3%A8me_partie",
              "attribution": "Marcel Proust · À la recherche du temps perdu",
