              "quote": "[…] façons majestueuses, simple avec les petites gens. Mais le coiffeur, chez qui le Prince avait une note arriérée d’au moins cinq ans et que les flacons de « Portugal », d’« Eau des Souverains », les fers, les rasoirs, les cuirs enflaient non moins que les shampoings, les coupes de cheveux, etc., plaçait plus haut Saint-Loup qui payait rubis sur l’ongle, avait plusieurs voitures et des chevaux de selle. Mis au courant de l’ennui de Saint-Loup de ne pouvoir partir avec sa maîtresse, il en parla chaudement au Prince ligoté d’un surplis blanc dans le moment que le barbier lui tenait la tête renversée et menaçait […]",
