              "quote": "[…] qu’il y avait erreur, que je ne connaissais pas M de Chaussegros. « Alors c’est sa sœur que vous connaissez, c’est la même chose. Elle vous a rencontré en Écosse. » Je n’étais jamais allé en Écosse et pris la peine inutile d’en avertir par honnêteté mon interlocuteur. C’était M de Chaussegros elle-même qui avait dit me connaître, et le croyait sans doute de bonne foi, à la suite d’une confusion première, car elle ne cessa jamais plus de me tendre la main quand elle m’apercevait. Et comme, en somme, le milieu que je fréquentais était exactement celui de M de Chaussegros, mon humilité ne rimait à rien. Que je […]",
