              "quote": "[…] nulle part celui du pain grillé. « Oui, oui, grommelait le maître d’hôtel, mais tout cela pourrait bien changer, les ouvriers doivent faire une grève au Canada et le ministre a dit l’autre soir à Monsieur qu’il a touché pour ça deux cent mille francs. » Le maître d’hôtel était loin de l’en blâmer, non qu’il ne fût lui-même parfaitement honnête, mais croyant tous les hommes politiques véreux, le crime de concussion lui paraissait moins grave que le plus léger délit de vol. Il ne se demandait même pas s’il avait bien entendu cette parole historique et il n’était pas frappé de l’invraisemblance qu’elle eût […]",
