              "quote": "[…] plus parler ensuite, il naît on ne sait trop comment, soit spontanément, soit par un hasard comparable à celui qui fit germer en France une mauvaise herbe d’Amérique dont la graine prise après la peluche d’une couverture de voyage était tombée sur un talus de chemin de fer, des modes d’expressions qu’on entend dans la même décade dites par des gens qui ne se sont pas concertés pour cela. Or, de même qu’une certaine année j’entendis Bloch dire en parlant de lui-même : « Comme les gens les plus charmants, les plus brillants, les mieux posés, les plus difficiles, se sont aperçus qu’il n’y avait qu’un seul être […]",
