              "quote": "[…] respirer les brises particulières au faubourg Saint-Germain, était aussi impossible que de faire la sieste dans l’oasis de Figuig, sans être par cela même en Afrique ? Il n’y a que l’imagination et la croyance qui peuvent différencier des autres certains objets, certains êtres, et créer une atmosphère. Hélas ! ces sites pittoresques, ces accidents naturels, ces curiosités locales, ces ouvrages d’art du faubourg Saint-Germain, il ne me serait sans doute jamais donné de poser mes pas parmi eux. Et je me contentais de tressaillir en apercevant de la haute mer (et sans espoir d’y jamais aborder) comme un minaret […]",
