        "champs": {
          "original": {
            "quote": "Après le raid de l’avant-veille, où le ciel avait été plus mouvementé que la terre, il s’était calmé comme la mer après une tempête. Mais comme la mer après une tempête il n’avait pas encore repris son apaisement absolu. Des aéroplanes montaient encore comme des fusées rejoindre les étoiles et des projecteurs promenaient lentement, dans le ciel sectionné, comme une pâle poussière d’astres, d’errantes voies lactées. Cependant les aéroplanes venaient s’insérer au milieu des constellations et on aurait pu se croire dans un autre hémisphère en effet, en voyant ces « étoiles nouvelles ». M. de Charlus me dit son […]",
            "language": "fr",
            "url": "https://fr.wikisource.org/wiki/Le_Temps_retrouv%C3%A9%2FII",
            "attribution": "Marcel Proust · À la recherche du temps perdu",
            "rightsUrl": "https://fr.wikisource.org/wiki/Auteur:Marcel_Proust",
            "type": "original"
          },
          "translations": {}
        },
        "foch": {
          "original": {
            "quote": "Maman allant justement à un petit thé chez M Sazerat, je n’eus aucun scrupule à me rendre à la matinée de la princesse de Guermantes. Je pris une voiture pour y aller, car le prince de Guermantes n’habitait plus son ancien hôtel mais un magnifique qu’il s’était fait construire avenue du Bois. C’est un des torts des gens du monde de ne pas comprendre que s’ils veulent que nous croyions en eux il faudrait d’abord qu’ils y crussent eux-mêmes, ou au moins qu’ils respectassent les éléments essentiels de notre croyance. Au temps où je croyais, même si je savais le contraire, que les Guermantes habitaient tel palais en […]",
            "language": "fr",
            "url": "https://fr.wikisource.org/wiki/Le_Temps_retrouv%C3%A9%2FIII",
            "attribution": "Marcel Proust · À la recherche du temps perdu",
            "rightsUrl": "https://fr.wikisource.org/wiki/Auteur:Marcel_Proust",
            "type": "original"
          },
          "translations": {}
        }
