              "quote": "[…] menacée, ils ont répandu le bruit que cette masse était destinée à une opération contre la Serbie. C’est ainsi qu’en 1800 l’armée qui allait opérer contre l’Italie était essentiellement qualifiée d’armée de réserve et semblait destinée non à passer les Alpes, mais à appuyer les armées engagées sur les théâtres septentrionaux. La ruse d’Hindenburg attaquant Varsovie pour masquer l’attaque véritable sur les lacs de Mazurie est imitée d’un plan de Napoléon de 1812. » Tu vois que M. Bidou reproduit presque les paroles que tu me rappelles et que j’avais oubliées. Et comme la guerre n’est pas finie, ces ruses-là se […]",
